std::string trim(std::string s){const auto first=s.find_first_not_of(" \t\r\n");if(first==std::string::npos)return {};return s.substr(first,s.find_last_not_of(" \t\r\n")-first+1);}
std::string lower(std::string s){for(char& c:s)if(c>='A'&&c<='Z')c=char(c-'A'+'a');return s;}
std::string pathString(const fs::path& p){return p.u8string();}
fs::path canonicalPath(const fs::path& p){std::error_code ec;auto c=fs::weakly_canonical(p,ec);return ec?fs::absolute(p).lexically_normal():c;}
bool readFile(const fs::path& p,std::string& out){std::ifstream f(p,std::ios::binary|std::ios::ate);if(!f)return false;const auto n=f.tellg();if(n<0||n>std::streamoff(32*1024*1024))return false;out.resize(size_t(n));f.seekg(0);if(n)f.read(out.data(),n);return bool(f);}
void appendUTF8(std::string& out,uint32_t cp){if(cp<128)out+=char(cp);else if(cp<2048){out+=char(0xc0|(cp>>6));out+=char(0x80|(cp&63));}else if(cp<65536){out+=char(0xe0|(cp>>12));out+=char(0x80|((cp>>6)&63));out+=char(0x80|(cp&63));}else {out+=char(0xf0|(cp>>18));out+=char(0x80|((cp>>12)&63));out+=char(0x80|((cp>>6)&63));out+=char(0x80|(cp&63));}}
bool decodeUTF8(const std::string& text,std::vector<uint32_t>& out){out.clear();for(size_t i=0;i<text.size();){unsigned char c=text[i++];uint32_t cp=0;unsigned n=0;if(c<128)cp=c;else if(c>=0xc2&&c<=0xdf){cp=c&31;n=1;}else if(c>=0xe0&&c<=0xef){cp=c&15;n=2;}else if(c>=0xf0&&c<=0xf4){cp=c&7;n=3;}else return false;if(i+n>text.size())return false;for(unsigned k=0;k<n;++k){unsigned char b=text[i++];if((b&0xc0)!=0x80)return false;cp=(cp<<6)|(b&63);}if((n==1&&cp<128)||(n==2&&cp<2048)||(n==3&&cp<65536)||cp>0x10ffff||(cp>=0xd800&&cp<=0xdfff))return false;out.push_back(cp);}return true;}
